-- Level templates by building type (Master Libraries > Level Templates).
--
-- Same model as WBS templates (20261021000002): a level template carries its sector
-- (template_category = projects.category slug) and the building types it fits (building_types =
-- projects.building_type slugs); pickers recommend matching templates. The old free-text
-- building_type column is no longer written by the app.
--
-- Seeds 21 level sets, bottom-up (the order levels are created in and what "floor below" means in
-- WBS templates), and links each seeded WBS template to its default level template where none is
-- chosen. Floor heights are typical starting values; GFA is left to each project. Skipped where a
-- template of the same name exists, so local edits are kept.

alter table public.level_naming_templates
  add column if not exists template_category text,
  add column if not exists building_types text[] not null default '{}';

comment on column public.level_naming_templates.template_category is
  'Sector slug (projects.category) this level template belongs to.';
comment on column public.level_naming_templates.building_types is
  'Building-type slugs (projects.building_type) this level template is recommended for; empty = any in its sector.';
comment on column public.level_naming_templates.building_type is
  'Deprecated free text (replaced by template_category + building_types).';

create or replace function public.save_level_template(p jsonb)
 returns uuid
 language plpgsql
 set search_path to 'public'
as $function$
declare
  v_id uuid := nullif(p->>'id', '')::uuid;
  v_types text[] := case when jsonb_typeof(p->'building_types') = 'array'
                         then array(select jsonb_array_elements_text(p->'building_types')) end;
begin
  if coalesce(btrim(p->>'template_name'), '') = '' then
    raise exception 'Template name is required' using errcode = '22023';
  end if;
  if v_id is null then
    insert into public.level_naming_templates
      (template_name, description, building_type, template_category, building_types, is_active, config, version)
    values (btrim(p->>'template_name'), nullif(p->>'description', ''), nullif(p->>'building_type', ''),
            nullif(p->>'template_category', ''), coalesce(v_types, '{}'),
            coalesce((p->>'is_active')::boolean, true), '[]'::jsonb, 1)
    returning id into v_id;
  else
    update public.level_naming_templates
       set template_name     = btrim(p->>'template_name'),
           description       = nullif(p->>'description', ''),
           building_type     = case when p ? 'building_type' then nullif(p->>'building_type', '') else building_type end,
           template_category = case when p ? 'template_category' then nullif(p->>'template_category', '') else template_category end,
           building_types    = coalesce(v_types, building_types),
           is_active         = coalesce((p->>'is_active')::boolean, is_active),
           version           = version + 1,
           updated_at        = now()
     where id = v_id;
    if not found then
      raise exception 'Template not found or not permitted' using errcode = '42501';
    end if;
    delete from public.level_template_items where template_id = v_id;
  end if;

  insert into public.level_template_items
    (template_id, sort_order, level_code, level_name, level_type, floor_height_m, typical_gfa_m2, source_level_id)
  select v_id, e.ord::int, upper(btrim(e.v->>'level_code')), btrim(e.v->>'level_name'),
         coalesce(nullif(e.v->>'level_type', ''), public.infer_level_type(e.v->>'level_code')),
         nullif(e.v->>'floor_height_m', '')::numeric, nullif(e.v->>'typical_gfa_m2', '')::numeric,
         nullif(e.v->>'source_level_id', '')::uuid
  from jsonb_array_elements(coalesce(p->'items', '[]'::jsonb)) with ordinality as e(v, ord);

  return v_id;
end $function$;

