eadwalls & backfill (roof)","cat":"infrastructure","types":["road","drainage"],"items":[{"level_code":"B01","level_name":"Base Slab","level_type":"basement","floor_height_m":null},{"level_code":"G00","level_name":"Walls","level_type":"ground","floor_height_m":null},{"level_code":"L01","level_name":"Top Slab","level_type":"typical","floor_height_m":null},{"level_code":"R00","level_name":"Headwalls & Backfill","level_type":"roof","floor_height_m":null}]},{"name":"Bridge – 3 Spans","desc":"Bridge for the Bridge & Structures WBS template: foundations (basement), piers & abutments (ground), one level per span (typical), deck finishes (roof); add or remove spans","cat":"infrastructure","types":["bridge"],"items":[{"level_code":"B01","level_name":"Foundations","level_type":"basement","floor_height_m":null},{"level_code":"G00","level_name":"Piers & Abutments","level_type":"ground","floor_height_m":null},{"level_code":"L01","level_name":"Span 1","level_type":"typical","floor_height_m":null},{"level_code":"L02","level_name":"Span 2","level_type":"typical","floor_height_m":null},{"level_code":"L03","level_name":"Span 3","level_type":"typical","floor_height_m":null},{"level_code":"R00","level_name":"Deck Finishes","level_type":"roof","floor_height_m":null}]},{"name":"Pump Station / Treatment Building","desc":"Pump station, treatment unit or substation for the Water Supply & Utility WBS template: wet well (basement), pump / process hall (ground), control floor (typical), roof","cat":"infrastructure","types":["water_supply","utility","other_infrastructure"],"items":[{"level_code":"B01","level_name":"Wet Well / Sump","level_type":"basement","floor_height_m":null},{"level_code":"G00","level_name":"Pump / Process Hall","level_type":"ground","floor_height_m":6},{"level_code":"L01","level_name":"Control Floor","level_type":"typical","floor_height_m":3.6},{"level_code":"R00","level_name":"Roof","level_type":"roof","floor_height_m":null}]},{"name":"Reservoir / Underground Tank","desc":"Ground or underground reservoir: tank base & walls (basement) and tank roof (roof)","cat":"infrastructure","types":["water_supply","other_infrastructure"],"items":[{"level_code":"B01","level_name":"Tank Base & Walls","level_type":"basement","floor_height_m":null},{"level_code":"R00","level_name":"Tank Roof","level_type":"roof","floor_height_m":null}]}]$lvl$::jsonb) loop
    continue when exists (select 1 from public.level_naming_templates where template_name = t->>'name');
    insert into public.level_naming_templates
      (template_name, description, template_category, building_types, is_active, config, version)
    values (t->>'name', t->>'desc', t->>'cat', array(select jsonb_array_elements_text(t->'types')), true, '[]'::jsonb, 1)
    returning id into v_id;
    insert into public.level_template_items (template_id, sort_order, level_code, level_name, level_type, floor_height_m)
    select v_id, e.ord::int, e.v->>'level_code', e.v->>'level_name', e.v->>'level_type', nullif(e.v->>'floor_height_m', '')::numeric
    from jsonb_array_elements(t->'items') with ordinality as e(v, ord);
  end loop;
end $seed$;

update public.wbs_templates w
   set default_level_template_id = l.id
  from jsonb_to_recordset($map$[{"wbs":"Residential – Villa & Landed House","lvl":"Villa – 2 Storey (G + 1)"},{"wbs":"Residential – High-rise Apartment / Condominium","lvl":"Residential Tower (2B + G + 20)"},{"wbs":"Residential – Housing Development / Estate","lvl":"Villa – 2 Storey (G + 1)"},{"wbs":"Commercial – Office, Retail & Mixed-use","lvl":"Office Tower (3B + G + M + 20)"},{"wbs":"Commercial – Hotel & Hospitality","lvl":"Hotel (2B + G + M + 2P + 12)"},{"wbs":"Commercial – Showroom & Restaurant Fit-out","lvl":"Showroom / Restaurant (G + Mezzanine)"},{"wbs":"Industrial – Factory & Manufacturing","lvl":"Factory – Production Hall + Mezzanine"},{"wbs":"Industrial – Warehouse & Logistics","lvl":"Warehouse – High-bay + Office Mezzanine"},{"wbs":"Institutional – School & University","lvl":"School (G + 3)"},{"wbs":"Institutional – Hospital & Clinic","lvl":"Hospital (2B + G + 2P + 6)"},{"wbs":"Institutional – Government & Religious Building","lvl":"Government Building (B + G + 5)"},{"wbs":"Infrastructure – Road & Drainage","lvl":"Box Culvert – Construction Stages"},{"wbs":"Infrastructure – Bridge & Structures","lvl":"Bridge – 3 Spans"},{"wbs":"Infrastructure – Water Supply & Utility Networks","lvl":"Pump Station / Treatment Building"}]$map$::jsonb) as m(wbs text, lvl text)
  join public.level_naming_templates l on l.template_name = m.lvl
 where w.template_name = m.wbs and w.default_level_template_id is null;
